#!/usr/bin/env python3
"""Scan every compact row and verify full destination slices by independent scipy paths."""
from pathlib import Path
import json,time
import numpy as np,pandas as pd,pyarrow.parquet as pq
from scipy.sparse import load_npz
from scipy.sparse.csgraph import dijkstra
from reconstruct_travel_matrix import ROOT,sha,load_mappings
start=time.time();receipt=json.loads((ROOT/'routing_receipt.json').read_text());assert receipt['output_manifest_sha256']==sha(ROOT/'candidate_travel_times_manifest.json');manifest,orig,dest=load_mappings();assert sum(x['rows'] for x in manifest['parts'])==receipt['pairs'];aliasinfo=json.loads((ROOT/manifest['entity_alias_receipt']['path']).read_text());base_count=int(aliasinfo['base_destinations']);chosenidx=np.unique(np.r_[np.linspace(0,base_count-1,5,dtype=int),np.flatnonzero(dest.id.isin(['ctx:RU-FED-MOW','ctx:RU-FED-SPB','RU-FED-MOW','RU-FED-SPB']))]);chosen=dest.iloc[chosenidx];pieces=[];rows=0;min_time=np.inf;max_time=0;invalid=0;self_counts=np.zeros(len(dest),dtype='int64');oc=orig.snap_km.to_numpy(float)*4;dc=dest.snap_km.to_numpy(float)*4;budgets=dest.routing_budget_minutes.to_numpy('float32');source_origin=pd.Index(orig.get('canonical_id',orig.id)).get_indexer(dest.get('canonical_id',dest.id));assert np.all(source_origin>=0)
for part in manifest['parts']:
 p=ROOT/part['path'];assert sha(p)==part['sha256'],str(p);table=pq.read_table(p);assert len(table)==part['rows'];oi=table['origin_index'].to_numpy();di=table['destination_index'].to_numpy();network=table['network_minutes'].to_numpy().copy();assert np.all(oi<len(orig)) and np.all(di<len(dest));connector=(oc[oi]+dc[di]).astype('float32');total=network+connector;same=oi==source_origin[di];total[same]=0;network[same]=0;self_counts+=np.bincount(di[same],minlength=len(dest));rows+=len(table);invalid+=int((~np.isfinite(total)|(total<0)|(network<0)|(total>budgets[di]+1e-4)).sum());min_time=min(min_time,float(total.min()));max_time=max(max_time,float(total.max()));take=np.isin(di,chosenidx)
 if np.any(take):pieces.append(pd.DataFrame({'origin_index':oi[take],'destination_index':di[take],'network_minutes':network[take],'travel_minutes':total[take]}))
assert rows==receipt['pairs'] and invalid==0;assert np.all(self_counts==1),'Every accepted destination must have exactly one self-pair'
actual=pd.concat(pieces,ignore_index=True);graph=load_npz(ROOT/'routing_graph.npz').transpose().tocsr();checks=[]
for center in chosen.itertuples():
 budget=float(center.routing_budget_minutes);distances=dijkstra(graph,directed=True,indices=int(center.road_node_index),limit=budget);network=distances[orig.road_node_index.to_numpy('int64')];minutes=network+(oc+center.snap_km*4);same=orig.get('canonical_id',orig.id).to_numpy()==getattr(center,'canonical_id',center.id);minutes[same]=0;network[same]=0;take=np.isfinite(minutes)&(minutes<=budget);expected=pd.DataFrame({'origin_index':np.flatnonzero(take),'network_expected':network[take],'total_expected':minutes[take]});got=actual[actual.destination_index==center.destination_index];merged=expected.merge(got,on='origin_index',how='outer',validate='one_to_one',indicator=True);matched=merged._merge.eq('both');omitted=merged._merge.eq('left_only');extra=merged._merge.eq('right_only');assert np.all(np.abs(merged.loc[omitted,'total_expected']-budget)<.05),'Missing interior-budget routes';assert np.all(np.abs(merged.loc[extra,'travel_minutes']-budget)<.05),'Extra routes away from budget boundary';error=np.abs(merged.loc[matched,'travel_minutes']-merged.loc[matched,'total_expected']);network_error=np.abs(merged.loc[matched,'network_minutes']-merged.loc[matched,'network_expected']);assert error.max()<.05 and network_error.max()<.05
 checks.append({'destination_id':center.id,'budget_minutes':budget,'expected_pairs':len(expected),'actual_pairs':len(got),'boundary_roundoff_only_pairs':int((~matched).sum()),'maximum_total_error_minutes':float(error.max()),'maximum_network_error_minutes':float(network_error.max())})
result={'status':'PASS','all_rows_scanned':rows,'invalid_rows':invalid,'every_destination_has_one_self_pair':True,'minimum_time_minutes':min_time,'maximum_time_minutes':max_time,'scipy_independent_shortest_path_checks':checks,'tolerance_minutes':.05,'note':'Float32 accumulated-time roundoff tolerated; same scenario graph, not external observed travel-time validation.','seconds':time.time()-start};tmp=ROOT/'matrix_verification.json.tmp';tmp.write_text(json.dumps(result,indent=2));tmp.replace(ROOT/'matrix_verification.json');receipt['status']='COMPUTED';receipt['matrix_verification_sha256']=sha(ROOT/'matrix_verification.json');tmp=ROOT/'routing_receipt.json.tmp';tmp.write_text(json.dumps(receipt,ensure_ascii=False,indent=2));tmp.replace(ROOT/'routing_receipt.json');print(json.dumps(result,indent=2))
